import{_ as t,o as d,c as o,aS as c}from"./chunks/framework.6vsn32Qq.js";const h=JSON.parse('{"title":"公共组件现状与后续路线","description":"","frontmatter":{},"headers":[],"relativePath":"catalog/component-roadmap.md","filePath":"catalog/component-roadmap.md","lastUpdated":null}'),r={name:"catalog/component-roadmap.md"};function a(i,e,n,l,y,s){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="公共组件现状与后续路线" tabindex="-1">公共组件现状与后续路线 <a class="header-anchor" href="#公共组件现状与后续路线" aria-label="Permalink to &quot;公共组件现状与后续路线&quot;">​</a></h1><p>状态：当前权威（能力盘点与后续任务入口）。本文件回答“已经有什么、还缺什么、下一项是什么、哪些只是旧项目来源、哪些多 renderer 入口尚未实现”。具体公开 interface、版本和可导入入口仍以各包 <code>package.json</code>、exports、声明、源码、测试与发布产物为准。</p><h2 id="使用规则" tabindex="-1">使用规则 <a class="header-anchor" href="#使用规则" aria-label="Permalink to &quot;使用规则&quot;">​</a></h2><ul><li>本文件不复制每个组件的完整 props、events、slots 或 expose；使用方式以目标包 README 和声明为准。</li><li><code>Published</code>、<code>Adopted</code> 等状态含义以 <a href="./component-lifecycle">公共能力生命周期</a> 为准。已发布不表示 <code>qy-permission</code>、<code>qy-origin-app</code> 或 <code>qy-workspace</code> 已采用。</li><li>“功能缺口”包括已确认的兼容债务和有来源证据的扩展点，不等于当前组件不可用，也不自动授权实施。</li><li>“未写 PRP”表示仍须先确认功能点、归属包、公共 interface 和验收入口；不能直接开始编码。</li></ul><h2 id="当前已经发布的能力" tabindex="-1">当前已经发布的能力 <a class="header-anchor" href="#当前已经发布的能力" aria-label="Permalink to &quot;当前已经发布的能力&quot;">​</a></h2><h3 id="qynpm-ui" tabindex="-1"><code>@qynpm/ui</code> <a class="header-anchor" href="#qynpm-ui" aria-label="Permalink to &quot;`@qynpm/ui`&quot;">​</a></h3><p>当前 <code>@qynpm/ui@1.0.34</code> 的根入口和子路径 exports 已覆盖下列能力；分组只用于导航，不改变组件归属。</p><table tabindex="0"><thead><tr><th>分组</th><th>已发布组件</th></tr></thead><tbody><tr><td>基础动作与展示</td><td><code>QyButton</code>、<code>QyIcon</code>、<code>QyLink</code>、<code>QyTag</code>、<code>QyBadge</code>、<code>QyAvatar</code>、<code>QyAlert</code>、<code>QyCard</code>、<code>QyEmpty</code>、<code>QyDivider</code>、<code>QyProgress</code>、<code>QyStatistic</code>、<code>QySkeleton</code>、<code>QySkeletonItem</code></td></tr><tr><td>输入与选择</td><td><code>QyInput</code>、<code>QyInputNumber</code>、<code>QyMoneyInput</code>、<code>QyDatePicker</code>、<code>QyCheckbox</code>、<code>QyCheckboxGroup</code>、<code>QyRadio</code>、<code>QyRadioGroup</code>、<code>QySwitch</code>、<code>QySelect</code>、<code>QyRemoteSelect</code>、<code>QySearchInput</code>、<code>QyAutocomplete</code>、<code>QyCascader</code>、<code>QyTreeSelect</code>、<code>QyColorPicker</code></td></tr><tr><td>数据与媒体</td><td><code>QyTree</code>、<code>QyDescriptions</code>、<code>QyDescriptionsItem</code>、<code>QyImage</code>、<code>QyImagePreview</code>、<code>QyImageUpload</code>、<code>QyUpload</code>、<code>QyFilePicker</code>、<code>QyRemarkImage</code>、<code>QyIframe</code>、<code>QyWatermark</code></td></tr><tr><td>浮层、导航与反馈</td><td><code>QyDialog</code>、<code>QyTooltip</code>、<code>QyPopover</code>、<code>QyPopconfirm</code>、<code>QyDropdown</code>、<code>QyTabs</code>、<code>QyTabPane</code>、<code>QySteps</code>、<code>QyStep</code>、<code>QyCollapse</code>、<code>QyCollapseItem</code>、<code>QyScrollbar</code>、<code>QyFullscreen</code>、<code>QyDrawer</code>、<code>QyResult</code></td></tr><tr><td>布局</td><td><code>QyRow</code>、<code>QyCol</code>、<code>QyContainer</code>、<code>QyAside</code>、<code>QyMain</code></td></tr><tr><td>组合能力</td><td><code>QySelectionDialog</code>、<code>QyLegacySelectionDialog</code>、<code>QyIconPicker</code>、<code>QyFormSection</code>、<code>QyActionBar</code>、<code>QyMenuActions</code>、<code>QyTableColumnSettings</code>、<code>QyRecordQuoteSearch</code></td></tr></tbody></table><p>本表反映当前发布包的入口，不表示每个历史消费者已经迁移，也不表示后文列出的增强功能已经包含在 V1 中。最新发布证据见 <a href="./../releases/2026-08-23-qynpm-ui-1.0.34-qyiframe">2026-08-23 @qynpm/ui 1.0.34 发布记录</a>。</p><h3 id="其他公共包" tabindex="-1">其他公共包 <a class="header-anchor" href="#其他公共包" aria-label="Permalink to &quot;其他公共包&quot;">​</a></h3><table tabindex="0"><thead><tr><th>包</th><th>当前稳定能力</th><th>后续主要关注点</th></tr></thead><tbody><tr><td><code>@qynpm/admin-patterns@1.0.4</code></td><td><code>QyPage</code>、<code>QySearchPanel</code>、<code>QySearchField</code>、<code>QyPagination</code>、<code>QyStatusTag</code>、<code>QyListActionBar</code>、<code>QyDetailPanel</code>、<code>QyDrawerForm</code>、<code>QyFormPanel</code>、<code>QyDictTag</code></td><td>Form/Drawer renderer 债务、真实消费者采用</td></tr><tr><td><code>@qynpm/rich-text@1.0.0</code></td><td><code>QyRichTextEditor</code> V1、<code>QyRichTextViewer</code> V1</td><td>真实消费者采用；Viewer 以 DOMPurify 安全 adapter 作为只读边界</td></tr><tr><td><code>@qynpm/excel-preview@1.0.0</code></td><td><code>QyExcelPreview</code> V1</td><td>真实消费者采用；x-data-spreadsheet 只作为内部 renderer，宿主负责数据和确认处理</td></tr><tr><td><code>@qynpm/admin-shell</code></td><td>Sidebar、Topbar、Tabs、Content 与 shell runtime</td><td>已冻结；无明确缺陷或第二 renderer 任务时不重做</td></tr><tr><td><code>@qynpm/form</code></td><td><code>useFormItem</code>、<code>useSave</code>、<code>QyQueryForm</code>、表单配置和查询同步</td><td>Element Plus/VNode 耦合较深；未来 renderer 迁移属于专项</td></tr><tr><td><code>@qynpm/table-schema</code> / <code>@qynpm/table</code></td><td>schema、Element renderer、行内编辑、菜单、图片、资料、列设置与 QyTable facade</td><td>ERP runtime adapter 和真实页面迁移验收仍有缺口</td></tr><tr><td><code>@qynpm/pickers@0.0.4</code></td><td>店铺、人员、角色人员、分类树、商品、商品分类菜单、报价单、属性、材质属性、工艺、基础产品和工序选择器</td><td>工序属性等复合选择能力继续逐项判断归属；消费者采用另行验收</td></tr><tr><td><code>@qynpm/product-preview</code></td><td>商品预览和预览表格</td><td>业务模块，不扩展成通用 renderer 工程</td></tr><tr><td><code>@qynpm/hooks@1.0.4</code></td><td>通用 hooks、QyLoading runtime/指令/插件、宿主 runtime、统一反馈</td><td>继续避免公开具体 UI 实例</td></tr><tr><td><code>@qynpm/qy-address-dialog</code></td><td>地址选择与编辑</td><td>大小写重复目录尚待单独裁决</td></tr></tbody></table><h2 id="已实现但仍有功能或兼容缺口" tabindex="-1">已实现但仍有功能或兼容缺口 <a class="header-anchor" href="#已实现但仍有功能或兼容缺口" aria-label="Permalink to &quot;已实现但仍有功能或兼容缺口&quot;">​</a></h2><p>下列项目应优先判断是“补现有模块”还是“新增模块”，不能因旧项目同名组件存在就直接重做。</p><table tabindex="0"><thead><tr><th>能力</th><th>当前事实</th><th>尚缺内容或待确认项</th><th>建议处理方式</th></tr></thead><tbody><tr><td><code>QyInput</code> / <code>QyInputTag</code> / <code>QyInputNumber</code> / <code>QyMoneyInput</code></td><td>根/子路径和 Qy-owned 公共类型已随 <code>@qynpm/ui@1.0.36</code> 发布</td><td>消费者尚未迁移或验收</td><td>保持当前运行时与使用方式；消费者采用另行验收</td></tr><tr><td>上传族</td><td><code>QyUpload</code> 已实现媒体上传与普通文件列表/只选择模式；<code>QyFilePicker</code> 保留为 Deprecated 兼容入口；<code>QyImageUpload</code> 保留图片字段薄封装</td><td>旧消费者仍有多套 <code>FileUpload</code> 和直接 <code>el-upload</code>，采用范围与业务协议迁移尚未执行</td><td>新调用优先使用 <code>QyUpload</code>，图片字段继续使用 <code>QyImageUpload</code>；宿主 <code>uploadRequest</code> 负责鉴权、baseURL、响应归一化和完整 URL；消费者迁移另立任务</td></tr><tr><td><code>QyTable</code> / <code>table-schema</code></td><td>基础 renderer 和多数旧 <code>useCol</code> 能力已具备；<code>qy-workspace</code> 约 375 个源码文件调用 <code>useCol()</code></td><td>ERP 权限过滤、确认反馈、浮层消息、列设置缓存 adapter、资料详情 adapter、真实 ERP 页面目测仍需接入</td><td>当前整体收益最高；作为 ERP adapter/消费者迁移任务，不塞进基础 UI</td></tr><tr><td><code>QyColorPicker</code> / <code>QyPopconfirm</code></td><td>根/子入口、Qy-owned 类型、文档与独立验收已完成，并随 <code>@qynpm/ui@1.0.34</code> 发布</td><td>尚未被消费者采用</td><td>保持冻结 V1 契约；消费者迁移另立任务</td></tr><tr><td><code>QyWatermark</code></td><td>UI 根/子入口、Qy-owned 类型、文档与独立验收已完成，并随 <code>@qynpm/ui@1.0.34</code> 发布；<code>table-schema</code> ImageCell 已从 <code>ElWatermark</code> 切换</td><td><code>@qynpm/table-schema</code> 尚未发布，UI peer 下限尚未调整</td><td>table-schema 发布与 peer 版本调整另立 release task；不迁移 qy-workspace 页面</td></tr><tr><td><code>QyPagination</code> 消费者迁移</td><td><code>@qynpm/admin-patterns</code> 已有 QyPagination；<code>qy-workspace</code> 约 270 个源码文件仍使用旧 Pagination</td><td>旧 <code>page / limit / pagination</code> 事件、页大小选项和 auto-scroll 与新接口存在迁移差异</td><td>优先在 qy-workspace 建私有兼容 adapter 并选择真实页面迁移；无新证据前不扩张公共 QyPagination interface</td></tr><tr><td><code>@qynpm/form</code></td><td>当前 Element Plus implementation 可用</td><td><code>FormItemSet</code>、规则、<code>ElFormItem</code>、VNode、<code>getFormProps()</code> 仍深度耦合；<code>useFormItem</code> 与 <code>useSave</code> 仍是配套关系</td><td>目标框架和消费者确定后再做专项，不新增平行完整表单逻辑</td></tr><tr><td><code>QyStatusTag</code></td><td>只展示调用方给出的 <code>label + tone</code></td><td>不负责把字典值映射为文案和 tone</td><td>由在制 <code>QyDictTag</code> 补映射层，不改写 <code>QyStatusTag</code></td></tr><tr><td><code>QyFormSection</code> / <code>QyAlert</code></td><td>两者均已发布</td><td><code>QyFormSection</code> 的 tip 仍是独立实现，尚未内部复用 <code>QyAlert</code></td><td>只在有一致性收益和回归证据时处理，不改变公开 interface</td></tr><tr><td><code>QyTableColumnSettings</code></td><td>已发布并由 table-schema 组合</td><td>旧 ERP 的缓存删除反馈和真实页面视觉仍需消费者 adapter 验证</td><td>跟随 ERP 表格迁移，不单独扩张 UI interface</td></tr><tr><td>地址弹窗</td><td>已发布</td><td><code>packages/QyAddressDialog</code> 与 <code>packages/qy-address-dialog</code> 同包名、仅大小写不同</td><td>单独 ADR/PRP 裁决权威目录；当前不删除或重命名</td></tr><tr><td>消费者采用</td><td>npm 包已发布</td><td><code>qy-permission</code>、<code>qy-origin-app</code>、<code>qy-workspace</code> 不会自动升级或迁移</td><td>每个消费者单独记录 package、lockfile、页面与构建证据</td></tr></tbody></table><h2 id="本批已发布能力" tabindex="-1">本批已发布能力 <a class="header-anchor" href="#本批已发布能力" aria-label="Permalink to &quot;本批已发布能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>归属包</th><th>状态</th><th>实施证据</th><th>当前边界</th></tr></thead><tbody><tr><td><code>QyDictTag</code></td><td><code>@qynpm/admin-patterns@1.0.4</code></td><td>Published</td><td>对应执行记录已通过独立验收；完整模板示例提供混合值、未知值和换行载体；发布证据见 <a href="./../releases/2026-08-13-components-release-batch">2026-08-13 批次</a>。</td><td>尚未被消费者采用；不迁移 qy-workspace/qy-permission。</td></tr><tr><td><code>QyRichTextEditor</code> / <code>QyRichTextViewer</code> V1</td><td><code>@qynpm/rich-text@1.0.0</code></td><td>Published</td><td>两份执行记录均已通过独立验收；完整模板覆盖编辑与安全查看；发布证据见 <a href="./../releases/2026-08-13-components-release-batch">2026-08-13 批次</a>。</td><td>尚未被消费者采用；不迁移旧 <code>RichTextBlock</code> 业务协议。</td></tr><tr><td><code>QyExcelPreview</code> V1</td><td><code>@qynpm/excel-preview@1.0.0</code></td><td>Published</td><td>对应执行记录已通过独立验收；完整模板覆盖受控 open、数据替换、只读列和确认结果；发布证据见 <a href="./../releases/2026-08-13-components-release-batch">2026-08-13 批次</a>。</td><td>尚未被消费者采用；不解析文件，不调用业务 API。</td></tr><tr><td>领域选择器批次</td><td><code>@qynpm/pickers@0.0.4</code></td><td>Published</td><td>角色人员、属性、材质属性、工艺、基础产品和工序选择器均已完成 PRP 与独立验收；根/子入口、类型和发布产物见 <a href="./../releases/2026-08-13-components-release-batch">2026-08-13 批次</a>。</td><td>尚未被消费者采用；不读取 store，不内置权限、路由或业务 API。</td></tr><tr><td><code>QyLoading</code> V1</td><td><code>@qynpm/hooks@1.0.4</code></td><td>Published</td><td>runtime、指令、插件和类型入口已随 <a href="./../releases/2026-08-21-qynpm-hooks-1.0.4-ui-1.0.32">2026-08-21 发布记录</a> 发布。</td><td>尚未被消费者采用；宿主负责 target renderer 与反馈语义。</td></tr><tr><td><code>QyDrawer</code> / <code>QyResult</code> V1</td><td><code>@qynpm/ui@1.0.32</code></td><td>Published</td><td>根/子路径、类型、文档和构建产物已随 <a href="./../releases/2026-08-21-qynpm-hooks-1.0.4-ui-1.0.32">2026-08-21 发布记录</a> 发布。</td><td>尚未被消费者采用；不把 Published 宣称为 Adopted。</td></tr></tbody></table><h2 id="尚未建设、需要先讨论的能力" tabindex="-1">尚未建设、需要先讨论的能力 <a class="header-anchor" href="#尚未建设、需要先讨论的能力" aria-label="Permalink to &quot;尚未建设、需要先讨论的能力&quot;">​</a></h2><h3 id="建议顺序" tabindex="-1">建议顺序 <a class="header-anchor" href="#建议顺序" aria-label="Permalink to &quot;建议顺序&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">顺序</th><th>候选能力</th><th>来源证据</th><th>当前结论</th><th>PRP 状态</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>ERP 表格 runtime adapter</td><td><code>qy-workspace</code> 约 375 个源码文件调用旧 <code>useCol()</code>，ERP 页面仍有权限、确认、消息、缓存和资料详情依赖</td><td>整体收益最高；归 <code>table-schema/table</code> 与宿主 adapter，不进入 UI</td><td>未写</td></tr><tr><td style="text-align:right;">2</td><td>上传族消费者迁移</td><td>公共上传族已完成选择/上传职责收敛，旧消费者仍存在多套上传实现</td><td>逐消费者建立宿主 adapter 并迁移；不把业务 transport 写回 UI 包</td><td>Implemented</td></tr><tr><td style="text-align:right;">3</td><td><code>QyPagination</code> 消费者迁移 adapter</td><td>旧 Pagination 覆盖约 270 个源码文件，现有 QyPagination 已具备核心分页能力</td><td>先做 qy-workspace 私有协议映射和真实页面迁移，不扩张公共组件</td><td>未写</td></tr><tr><td style="text-align:right;">4</td><td>富文本编辑与只读展示</td><td><code>packages/qiyin/components/QuillEditor</code>、<code>QullView</code>，<code>qy-origin-app</code> 有 <code>RichTextBlock</code></td><td><code>QyRichTextEditor</code> 与 <code>QyRichTextViewer</code> V1 已发布；旧业务协议仍留在宿主</td><td>Published</td></tr><tr><td style="text-align:right;">5</td><td>表格文件预览/导入</td><td><code>excelPreview</code>、<code>excelSheetPreview</code> 等旧共享能力</td><td><code>QyExcelPreview</code> V1 已发布；文件解析、导入 API 和业务字段仍留在宿主</td><td>Published</td></tr><tr><td style="text-align:right;">6</td><td>角色人员及领域选择器</td><td><code>SelectStaffByRole</code>、属性、工艺、基础产品、机器/工序等旧组件</td><td>角色人员、属性、材质属性、工艺、基础产品和工序选择器 V1 已发布；工序属性选择保持独立候选</td><td>Published</td></tr><tr><td style="text-align:right;">7</td><td>工序属性选择器</td><td>foundation <code>SelectProcessAttribute</code> 旧组件及机器信息页消费证据</td><td><code>QyProcessAttributePicker</code> V1 已实现、独立验收并随 <code>@qynpm/pickers@0.0.5</code> 发布；复制格式保持旧版完整对象数组，不迁移消费者</td><td>Published</td></tr></tbody></table><h3 id="已知低优先级扩展点" tabindex="-1">已知低优先级扩展点 <a class="header-anchor" href="#已知低优先级扩展点" aria-label="Permalink to &quot;已知低优先级扩展点&quot;">​</a></h3><p>这些内容来自已执行 PRP 的明确非目标或旧项目线索，目前没有足够收益进入近期队列。</p><table tabindex="0"><thead><tr><th>扩展点</th><th>当前处理</th></tr></thead><tbody><tr><td><code>QyHeader</code> / <code>QyFooter</code></td><td><code>QyContainer</code> V1 明确暂缓；先证明跨消费者使用和方向协议收益</td></tr><tr><td>Splitter、拖拽侧栏、自动响应式堆叠</td><td>不是基础 Container V1 职责；有真实布局消费者后独立设计</td></tr><tr><td><code>QyAvatarGroup</code></td><td>当前无第二消费者证据，暂缓</td></tr><tr><td><code>QyStatistic</code> 趋势、倒计时、图表</td><td>属于复合统计模块，不扩张基础 Statistic</td></tr><tr><td><code>QySwitch</code> 异步 <code>beforeChange</code>、业务确认</td><td>保持业务/宿主控制；出现重复受控需求后再评估</td></tr><tr><td><code>QyInlineEditInput</code> / <code>QyAutocompleteInput</code></td><td>目前先留在 table-schema renderer；只有表格外真实复用时再进入 UI</td></tr><tr><td>Grid 业务断点预设、自动列数</td><td>由页面布局或上层 pattern 负责，不扩张基础 24 栅格</td></tr></tbody></table><h2 id="qy-workspace-跨系统来源对照" tabindex="-1">qy-workspace 跨系统来源对照 <a class="header-anchor" href="#qy-workspace-跨系统来源对照" aria-label="Permalink to &quot;qy-workspace 跨系统来源对照&quot;">​</a></h2><p>2026-08-10 现场复算覆盖 <code>packages/*/src/components</code> 下 13 个业务包、745 个 Vue/TSX/JSX 组件文件，并交叉检查 <code>packages/qiyin/components</code>。重复名称只是候选证据，是否公共化仍取决于实现差异和业务耦合。</p><table tabindex="0"><thead><tr><th>旧能力</th><th style="text-align:right;">分布证据</th><th>对照结论</th></tr></thead><tbody><tr><td><code>SvgIcon</code></td><td style="text-align:right;">11 个系统</td><td><code>QyIcon</code> 已承接</td></tr><tr><td><code>IconSelect</code></td><td style="text-align:right;">9 个系统，目标文件完全相同</td><td><code>QyIconPicker</code> 已承接</td></tr><tr><td><code>Screenfull</code></td><td style="text-align:right;">8 个系统，目标文件完全相同</td><td><code>QyFullscreen</code> 已承接</td></tr><tr><td><code>FileUpload</code></td><td style="text-align:right;">10 个系统，多套实现</td><td>转入上传族兼容审查</td></tr><tr><td><code>DictTag</code></td><td style="text-align:right;">5 个系统，目标文件完全相同</td><td><code>QyDictTag</code> 已随 <code>@qynpm/admin-patterns@1.0.4</code> 发布，消费者尚未采用</td></tr><tr><td><code>Category</code></td><td style="text-align:right;">6 个系统，多套实现</td><td>含分类数据和交互业务，暂不做基础 UI</td></tr><tr><td><code>SelectStaff</code></td><td style="text-align:right;">5 个系统，多套实现</td><td>由 pickers/业务 adapter 评估</td></tr><tr><td><code>Log</code></td><td style="text-align:right;">5 个系统，多套实现</td><td>接口和业务结构不同，保留在领域包</td></tr><tr><td><code>Breadcrumb</code>、<code>HeaderSearch</code>、<code>Hamburger</code>、<code>TopNav</code> 等</td><td style="text-align:right;">多个旧后台系统重复</td><td>由 admin-shell/admin-framework 整体承接，不逐个重做</td></tr><tr><td>成套报价、Canvas/三维预览、订单关系、工艺表单</td><td style="text-align:right;">多个业务目录存在复制或近似实现</td><td>迁入未来 qy-workspace 领域包或业务公共包，不进入通用 UI</td></tr></tbody></table><p>更详细的消费者角色和禁止迁入内容见 <a href="./../consumers/qy-workspace">qy-workspace 迁移来源</a>。</p><h2 id="多-renderer-与多入口-当前未实现项" tabindex="-1">多 renderer 与多入口：当前未实现项 <a class="header-anchor" href="#多-renderer-与多入口-当前未实现项" aria-label="Permalink to &quot;多 renderer 与多入口：当前未实现项&quot;">​</a></h2><p>当前只有 Vue 3 + Element Plus implementation。下表中的入口和实现均尚未存在；这是明确暂缓的架构工作，不是当前发布缺陷。</p><table tabindex="0"><thead><tr><th>模块</th><th>当前真实入口</th><th>尚未实现</th><th>未来触发后优先方向</th></tr></thead><tbody><tr><td><code>@qynpm/form</code></td><td>只有包根入口</td><td><code>@qynpm/form/element</code>、<code>@qynpm/form/naive</code>、Naive adapter</td><td>先冻结共享 schema/core，再由同包可选子路径承载 renderer；根入口保留兼容策略，不能维护两套业务逻辑</td></tr><tr><td><code>@qynpm/ui</code></td><td>根入口和按组件子路径，内部以 Element Plus 为主</td><td>Naive UI 第二 implementation、运行时 framework prop/provider、全局 renderer 注册器</td><td>简单组件优先保持业务导入不变并替换内部 implementation；复杂组件按模块增加真实 adapter，不建立全量平行入口</td></tr><tr><td><code>@qynpm/table-schema</code></td><td>当前包根入口；已有内部 core/Element 目录证据</td><td>对外 Element/Naive renderer 子路径、第二表格 renderer</td><td>保留 schema core；目标表格框架确定后单独设计 renderer 包或子路径</td></tr><tr><td><code>@qynpm/table</code></td><td>当前 Qy facade + Element renderer</td><td>第二表格 renderer</td><td>先验证同一 QyTable interface 能否覆盖目标框架差异，再决定入口形态</td></tr><tr><td><code>@qynpm/admin-patterns</code></td><td>当前包根入口，部分模块已有内部 seam</td><td>Naive Drawer/Form/Pagination 等 adapter</td><td>先迁基础控件和 form/table，再迁 patterns；页面语义模块通常无需框架子路径</td></tr><tr><td><code>@qynpm/admin-shell</code></td><td>当前包根入口</td><td>第二套 Tabs/Topbar/Sidebar renderer</td><td>Shell 已冻结，只有明确目标框架和消费者时才立项</td></tr><tr><td><code>@qynpm/pickers</code> 与业务包</td><td>根入口及现有选择器子路径</td><td>第二套交互 renderer</td><td>保留业务请求/字段协议，共享 core；仅替换选择交互 implementation</td></tr></tbody></table><h3 id="启动第二-renderer-的必要条件" tabindex="-1">启动第二 renderer 的必要条件 <a class="header-anchor" href="#启动第二-renderer-的必要条件" aria-label="Permalink to &quot;启动第二 renderer 的必要条件&quot;">​</a></h3><p>只有同时满足以下条件，才能把上表项目从“暂缓”升级为 Planned：</p><ol><li>已确定目标框架和首个真实消费者。</li><li>已列出当前 Qy interface 与目标框架的行为差异，而不是只比较组件名称。</li><li>已决定 peer dependency、构建产物、exports、样式 tokens 和宿主 runtime。</li><li>已有同一行为矩阵可同时验收当前 implementation 与第二 adapter。</li><li>已证明新增入口比消费者自行适配更有长期收益。</li></ol><p>在这些条件满足前，新组件仍需预留可替换 implementation 的 seam，但不创建空的 <code>/naive</code>、<code>/element</code>、provider 或注册器。</p><h2 id="后续文档工作顺序" tabindex="-1">后续文档工作顺序 <a class="header-anchor" href="#后续文档工作顺序" aria-label="Permalink to &quot;后续文档工作顺序&quot;">​</a></h2><ol><li><code>QyDictTag</code>、<code>@qynpm/rich-text</code>、<code>@qynpm/excel-preview</code> 与领域选择器批次已经发布；后续由具体消费者独立采用和验收。</li><li>按 ERP 真实页面建立 table runtime adapter 迁移卡，不把宿主权限和接口写进公共包；这是当前整体收益最高的候选。</li><li>QyDialog 与旧协议桥接 PRP（内部记录：<code>docs/prps/qy-dialog-v2-legacy-bridge-v1/overview.md</code>）已完成核心、legacy 包、公共消费者桥接与独立验收，并随 <a href="./../releases/2026-08-23-qydialog-release-batch">2026-08-23 发布批次</a> 发布；消费者迁移另立任务。</li><li>上传族公共边界已经收敛；后续只在获授权后逐消费者建立 transport/业务 adapter 并迁移。</li><li>为旧 Pagination 建 qy-workspace 私有迁移 adapter，以真实页面验证后再决定是否存在公共接口缺口。</li><li>富文本、表格文件预览/导入、领域选择器分别形成候选说明；前两项已有在制 PRP，后续仍须以长期文档承接边界。</li><li>第二 renderer 只有满足触发条件后才新增 ADR 和分阶段 PRP；当前不提前创建实现任务。</li></ol>',35)])])}const m=t(r,[["render",a]]);export{h as __pageData,m as default};
